// Adaptador genérico de entrada: cuerpo crudo, cabeceras y fuente (?source=<puerto>.<nombre>)
const item = $input.first();
let raw = '';
try { raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch (e) { raw = JSON.stringify(item.json.body || {}); }
const h = item.json.headers || {};
const headers = Object.fromEntries(Object.entries(h).map(([k, v]) => [String(k).toLowerCase(), Array.isArray(v) ? v[0] : v]));
return [{ json: { source: String(item.json.query?.source || 'desconocido'), raw, headers, body: item.json.body || {} } }];

// Adaptador genérico de entrada: arma el callback sys.callback.v1 según inbound[<source>]
//   event_id_path   : ruta del ID único del evento en el cuerpo, o lista de rutas que se unen con ':'
//                     (p. ej. ["data.id", "data.status"]); si falta, se usa el sha256 del cuerpo
//   event_type_path : ruta del tipo de evento en el cuerpo
//   event_type      : tipo fijo (si no hay event_type_path)
//   event_type_map  : tipo del proveedor → tipo normalizado del puerto
//   payload_map     : campo normalizado → ruta en el cuerpo (si falta, se entrega el cuerpo completo)
//   status_field / status_map : normalización del estado, igual que en la salida
const w = $('Leer solicitud').first().json;
const chk = $json.chk || {};
const cfg = chk.settings || {};
const b = w.body || {};
const get = (obj, path) => String(path).split('.').reduce((a, k) => {
  if (a === undefined || a === null) return undefined;
  const m = k.match(/^(.*)\[(\d+)\]$/);
  return m ? (m[1] ? a[m[1]] : a)?.[Number(m[2])] : a[k];
}, obj);
const eventId = Array.isArray(cfg.event_id_path) ? cfg.event_id_path.map(p => get(b, p) ?? '').join(':') : (cfg.event_id_path ? get(b, cfg.event_id_path) : null);
const rawType = cfg.event_type_path ? get(b, cfg.event_type_path) : cfg.event_type;
const eventType = (cfg.event_type_map || {})[rawType] || rawType || 'unmapped';
let payload = b;
if (cfg.payload_map) { payload = {}; for (const [k, p] of Object.entries(cfg.payload_map)) payload[k] = get(b, p) ?? null; }
if (cfg.status_field && cfg.status_map && payload && typeof payload === 'object') {
  const raw = payload[cfg.status_field];
  payload.provider_status = raw ?? null;
  payload[cfg.status_field] = cfg.status_map[raw] ?? cfg.status_map['*'] ?? 'unknown';
}
return [{ json: { source: w.source, external_event_id: String(eventId ?? chk.body_sha256), event_type: eventType, signature_valid: chk.signature_valid === true, payload, envelope: {} } }];

